// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 _value) public {
        // Bound _value to a reasonable range (e.g., <= initial balance of owner)
        vm.assume(_value <= 200000000e18); // owner's balance starts as totalDistributed

        // First call XBornID() to set balances
        c.XBornID();

        // Get initial totalDistributed after XBornID()
        uint256 totalDistBeforeBurn = c.totalDistributed();
        uint256 totalSupplyBeforeBurn = c.totalSupply();

        // Perform burn
        c.burn(_value);

        // Read state after burn
        uint256 totalDistAfterBurn = c.totalDistributed();
        uint256 totalSupplyAfterBurn = c.totalSupply();

        // General rule: totalDistributed should decrease (or stay same) when burning, never increase
        // In correct contract: totalDistributed = totalDistributed - _value
        // So totalDistAfterBurn should be <= totalDistBeforeBurn
        // The bug makes it increase, so this assertion fails on mutant
        assertTrue(totalDistAfterBurn <= totalDistBeforeBurn, "totalDistributed should not increase after burn");
    }
}

